#include <bits/stdc++.h>
using namespace std;

void solve() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    const int Z = 100;
    const int N = Z * Z;
    const int M = Z * Z * Z * 3;
    vector<int> px(N), py(N), head(N, -1), to(M), ct(M), w(M), nt(M);
    vector<int> d_arr(N), vis(N), pre(N), id(N);
    int tot = 0;

    auto add = [&](int u, int v, int flow, int cost) {
        to[tot] = v; ct[tot] = cost; w[tot] = flow; nt[tot] = head[u]; head[u] = tot++;
        to[tot] = u; ct[tot] = -cost; w[tot] = 0; nt[tot] = head[v]; head[v] = tot++;
    };

    auto init = [&]() {
        fill(head.begin(), head.end(), -1);
        tot = 0;
    };

    auto spfa = [&](int s, int t) {
        queue<int> q;
        fill(d_arr.begin(), d_arr.end(), INT_MAX);
        fill(vis.begin(), vis.end(), 0);
        fill(pre.begin(), pre.end(), -1);
        d_arr[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            vis[u] = 0;
            for (int i = head[u]; i != -1; i = nt[i]) {
                if (w[i] > 0 && d_arr[to[i]] > d_arr[u] + ct[i]) {
                    d_arr[to[i]] = d_arr[u] + ct[i];
                    pre[to[i]] = u;
                    id[to[i]] = i;
                    if (!vis[to[i]]) {
                        vis[to[i]] = 1;
                        q.push(to[i]);
                    }
                }
            }
        }
        return d_arr[t] < INT_MAX;
    };

    auto MaxFlow = [&](int s, int t) {
        int sum = 0, total_cost = 0;
        while (spfa(s, t)) {
            int flow = INT_MAX;
            for (int i = t; i != s; i = pre[i]) {
                flow = min(flow, w[id[i]]);
            }
            for (int i = t; i != s; i = pre[i]) {
                w[id[i]] -= flow;
                w[id[i] ^ 1] += flow;
            }
            total_cost += d_arr[t] * flow;
            sum += flow;
        }
        return total_cost;
    };

    int s = 0, t = n * 100 + 1;
    init();
    for (int i = 1; i <= 100; ++i)
        add(i, t, 100, 0);
    for (int i = 1, v; i <= k; ++i) {
        cin >> v;
        add(s, (v - 1) * 100 + 1, 1, 0);
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j < 100; ++j) {
            add((i - 1) * 100 + j, (i - 1) * 100 + j + 1, 100, c);
        }
    }
    for (int i = 1, u, v; i <= m; ++i) {
        cin >> u >> v;
        for (int j = 1; j < 100; ++j) {
            int idx = (u - 1) * 100 + j;
            int idy = (v - 1) * 100 + j + 1;
            for (int k = 1; k <= 50; ++k) {
                add(idx, idy, 1, c + (k * k - (k - 1) * (k - 1)) * d);
            }
        }
        for (int j = 1; j < 100; ++j) {
            int idx = (v - 1) * 100 + j;
            int idy = (u - 1) * 100 + j + 1;
            for (int k = 1; k <= 50; ++k) {
                add(idx, idy, 1, c + (k * k - (k - 1) * (k - 1)) * d);
            }
        }
    }
    cout << MaxFlow(s, t) << "\n";
}

int main() {
    solve();
    return 0;
}
